Let \[f(x) =
\begin{cases}
x^2+3 &\text{if } x<n, \\
2x+7 &\text{if }x\ge{n}.
\end{cases}
\] Determine the sum of all possible values of \( n \) such that \( y=f(x) \) is continuous.

Given the graph of \( y = g(x) \):

[asy]
unitsize(0.5 cm);

real func(real x) {
  real y;
  if (x >= -4 && x <= -1) {y = 2*x + 8;}
  if (x >= -1 && x <= 1) {y = -x^2 + 2;}
  if (x >= 1 && x <= 4) {y = -2*(x - 3);}
  return(y);
}

int i;

for (i = -5; i <= 5; ++i) {
  draw((i,-5)--(i,5),gray(0.7));
  draw((-5,i)--(5,i),gray(0.7));
}

draw((-5,0)--(5,0),Arrows(6));
draw((0,-5)--(0,5),Arrows(6));

label("$x$", (5,0), E);
label("$y$", (0,5), N);

draw(graph(func,-4,4),red);

label("$y = g(x)$", (4,-2), UnFill);
[/asy]

Which is the graph of \( y = g(-x) \)?

[asy]
unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  real y;
  if (x >= -4 && x <= -1) {y = 2*x + 8;}
  if (x >= -1 && x <= 1) {y = -x^2 + 2;}
  if (x >= 1 && x <= 4) {y = -2*(x - 3);}
  return(y);
}

real funcb(real x) {
  return(-func(x));
}

real funcd(real x) {
  return(-func(-x));
}

real funce(real x) {
  return(func(-x));
}

for (n = 1; n <= 5; ++n) {
  graf[n] = new picture;
  for (i = -5; i <= 5; ++i) {
    draw(graf[n],(i,-5)--(i,5),gray(0.7));
    draw(graf[n],(-5,i)--(5,i),gray(0.7));
  }
  draw(graf[n],(-5,0)--(5,0),Arrows(6));
  draw(graf[n],(0,-5)--(0,5),Arrows(6));

  label(graf[n],"$x$", (5,0), E);
  label(graf[n],"$y$", (0,5), N);
}

draw(graf[1],graph(func,-4,4),red);
draw(graf[2],graph(funcb,-4,4),red);
draw(graf[3],(-4,2)--(-3,0),red);
draw(graf[3],arc((-1,2),2,180,360),red);
draw(graf[3],(1,2)--(4,0),red);
draw(graf[4],graph(funcd,-4,4),red);
draw(graf[5],graph(funce,-4,4),red);

label(graf[1], "A", (0,-6));
label(graf[2], "B", (0,-6));
label(graf[3], "C", (0,-6));
label(graf[4], "D", (0,-6));
label(graf[5], "E", (0,-6));

add(graf[1]);
add(shift((12,0))*(graf[2]));
add(shift((24,0))*(graf[3]));
add(shift((6,-12))*(graf[4]));
add(shift((18,-12))*(graf[5]));
[/asy]

